import { useEffect, useState } from "react";
import api from "./api";
import CodeEditor from "./CodeEditor";
import LevelsSidebar from "./LevelsSidebar";

export default function App() {
  const userId = 1;

  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(1);
  const [selectedLevel, setSelectedLevel] = useState(null);
  const [level, setLevel] = useState(null);

  const [language, setLanguage] = useState("python");
  const [code, setCode] = useState("");
  const [input, setInput] = useState("");
  const [output, setOutput] = useState("");
  const [error, setError] = useState("");

  const [locked, setLocked] = useState(false);
  const [readOnly, setReadOnly] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  /* ================= LOAD LEVELS ================= */
  useEffect(() => {
    api
      .get(`/levels/${userId}`)
      .then((res) => {
        setLevels(res.data.levels);
        setCurrentLevel(res.data.currentLevel);
      })
      .catch(() => setError("Failed to load levels"));
  }, []);

  /* ================= LOAD CLICKED LEVEL ================= */
  useEffect(() => {
    const lvl = selectedLevel ?? currentLevel;

    api
      .get(`/level/${userId}/${lvl}`)
      .then((res) => {
        setLevel(res.data.level);
        setLocked(res.data.locked);
        setReadOnly(res.data.readOnly);
        setCode("");
        setInput("");
        setOutput("");
      })
      .catch(() => setError("Failed to load level"));
  }, [selectedLevel, currentLevel]);

  if (error) return <h2>{error}</h2>;
  if (!level) return <h2>Loading...</h2>;

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* ===== SIDEBAR ===== */}
      <div style={{ width: 260, borderRight: "1px solid #ddd" }}>
        <LevelsSidebar
          levels={levels}
          currentLevel={currentLevel}
          onSelectLevel={(lvl) => {
            setSelectedLevel(lvl);
            setSidebarOpen(false);
          }}
        />
      </div>

      {/* ===== MAIN ===== */}
      <div style={{ flex: 1, padding: 20 }}>
        {/* ===== PROBLEM ===== */}
        <div style={{ marginBottom: 20 }}>
          <h2>
            Level {level.level_no}: {level.title}
          </h2>
          <p>{level.description}</p>

          {locked && readOnly && (
            <p style={{ color: "orange" }}>🔒 Previous level (Read-only)</p>
          )}
          {locked && !readOnly && (
            <p style={{ color: "red" }}>🔒 Level locked</p>
          )}
        </div>

        {/* ===== EDITOR ===== */}
        <CodeEditor
          code={code}
          setCode={readOnly ? () => {} : setCode}
        />

        {/* ===== BUTTONS ===== */}
        <div style={{ marginTop: 10 }}>
          <button
            onClick={async () => {
              if (!input.trim()) {
                alert("Input required");
                return;
              }
              const res = await api.post("/run", {
                code,
                language,
                input,
              });
              setOutput(res.data.output);
            }}
            disabled={locked}
          >
            ▶ Run
          </button>

          <button
            style={{ marginLeft: 10 }}
            disabled={locked || readOnly}
            onClick={async () => {
              const res = await api.post("/submit", {
                userId,
                code,
                language,
              });

              alert(res.data.verdict);

              if (res.data.verdict.includes("Accepted")) {
                setCurrentLevel((prev) => prev + 1);
                setSelectedLevel(null);
              }
            }}
          >
            ✔ Submit
          </button>
        </div>

        {/* ===== INPUT / OUTPUT ===== */}
        <div style={{ display: "flex", marginTop: 20, gap: 20 }}>
          <textarea
            rows={6}
            style={{ width: "50%" }}
            placeholder="Input (Run only)"
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />

          <pre style={{ width: "50%", background: "#f3f3f3", padding: 10 }}>
            {output || "Output will appear here"}
          </pre>
        </div>
      </div>
    </div>
  );
}

/* ✅ CSS-IN-JS Modern UI */
const styles = {
  page: {
    background: "#0f172a",
    color: "#f1f5f9",
    minHeight: "100vh",
    fontFamily: "Inter, sans-serif",
  },

  navbar: {
