    flex: 1,
    padding: 16,
    overflowY: "auto",

  },

  card: {
    borderRadius: 14,
    padding: 16,
    boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
    marginBottom: 14,
      background: "#1e293b",
  },

  cardHeader: {
    display: "flex",
    alignItems: "center",
